"""Raw embedding cache and fit-only transforms (two separate layers).

Layer 1 — raw cache: frozen-encoder output per (task, split), bound to an identity
record containing checkpoint sha256, encoder-module sha256, source CSV sha256, full
ordered row identity (every Drug_ID/Drug pair), feature dim, dtype, finiteness
digests and the parse mask. A cache is only accepted after ALL of these match;
file existence or row counts alone never suffice.

Layer 2 — fit transform: feature standardization whose statistics are fitted ONLY
on the official-train fit partition (never internal-stop rows, never valid/test).
Regression target standardization likewise fits on the fit partition only. The
transform object carries its fit-partition identity so misuse is detectable.

Unparseable rows keep their position, get the documented constant zero raw fill
before scaling, and remain visible through the parse mask. No cleaning happens.
"""

from __future__ import annotations

import json
from dataclasses import dataclass
from pathlib import Path
from typing import Any, Mapping, Sequence

from .common import (CHEMELEON_SHA256, FEATURE_DIM, GLOBAL_FILL_VALUE,
                     InterfaceError, array_digest, canonical_json_bytes,
                     row_identity_sha256, sha256_hex, sha256_file, write_json)


def _module_sha256() -> dict[str, str]:
    base = Path(__file__).resolve().parent
    out = {}
    for name in ("encoder.py", "cache.py", "data_io.py", "heads.py"):
        p = base / name
        out[name] = sha256_file(p) if p.is_file() else "absent"
    return out


def cache_contract(task: str, split: str, source_sha256: str,
                   rows: Sequence[Mapping[str, str]]) -> dict[str, Any]:
    """Identity binding a raw cache entry to data + implementation + full row order."""
    from importlib.metadata import version as _pkg_version
    pkgs = {}
    for pkg in ("chemprop", "rdkit", "torch", "numpy"):
        try:
            pkgs[pkg] = _pkg_version(pkg)
        except Exception:
            pkgs[pkg] = "absent"
    return {
        "version": 1,
        "task": task,
        "split": split,
        "feature_dim": FEATURE_DIM,
        "fill_value": GLOBAL_FILL_VALUE,
        "encoder_checkpoint_sha256": CHEMELEON_SHA256,
        "implementation_sha256": _module_sha256(),
        "packages": pkgs,
        "source_csv_sha256": source_sha256,
        "n_rows": len(rows),
        "row_identity_sha256": row_identity_sha256(rows),
    }


def cache_paths(cache_root: Path, task: str, split: str):
    d = cache_root / task
    return (d / f"raw_{split}.npy", d / f"mask_{split}.npy",
            d / f"raw_{split}.meta.json")


def build_raw_cache(embedder, task: str, split: str, rows: Sequence[Mapping[str, str]],
                    source_sha256: str, cache_root: Path,
                    contract: dict[str, Any] | None = None) -> dict[str, Any]:
    """Encode every row of one split (deduplicating identical SMILES strings within
    the split, broadcasting back to each original row index) and persist the cache.

    Returns the identity record. Caller must supply rows already loaded unchanged.
    """
    import numpy as np

    smiles = [r["Drug"] for r in rows]
    uniq = list(dict.fromkeys(smiles))
    u_emb, u_ok = embedder.embed(uniq)
    pos = {s: i for i, s in enumerate(uniq)}
    take = np.asarray([pos[s] for s in smiles], dtype=np.int64)
    emb, ok = u_emb[take], u_ok[take]
    if emb.shape != (len(rows), embedder.feature_dim):
        raise InterfaceError(f"{task}/{split}: unexpected embedding shape {emb.shape}")
    if embedder.feature_dim != FEATURE_DIM or ok.shape != (len(rows),) or ok.dtype != np.bool_:
        raise InterfaceError("encoder dimension/parse mask does not match cache contract")
    if not np.isfinite(emb[ok]).all():
        raise InterfaceError("non-finite output on a parsed row must not be zero-filled")
    filled = np.asarray(emb, dtype=np.float32).copy()
    filled[~ok] = np.float32(GLOBAL_FILL_VALUE)
    arr_p, mask_p, meta_p = cache_paths(cache_root, task, split)
    arr_p.parent.mkdir(parents=True, exist_ok=True)
    np.save(arr_p, np.ascontiguousarray(filled))
    np.save(mask_p, ok)
    contract = contract or cache_contract(task, split, source_sha256, rows)
    meta = {
        "contract": contract,
        "files": {"arr": sha256_file(arr_p), "mask": sha256_file(mask_p)},
        "identity": {
            "features": array_digest(filled),
            "parse_mask": array_digest(ok),
            "parsed_true_count": int(ok.sum()),
            "unparsed_row_indices": [int(i) for i in np.nonzero(~ok)[0]],
        },
    }
    write_json(meta_p, meta)
    load_raw_cache(cache_root, task, split, rows, source_sha256)
    return meta


def load_raw_cache(cache_root: Path, task: str, split: str,
                   rows: Sequence[Mapping[str, str]], source_sha256: str):
    """Validate-and-load a raw cache entry against live input identity.

    Raises InterfaceError on any contract/row-order/content mismatch; never falls
    back to silent acceptance.
    """
    import numpy as np

    arr_p, mask_p, meta_p = cache_paths(Path(cache_root), task, split)
    for p in (arr_p, mask_p, meta_p):
        if not p.is_file():
            raise InterfaceError(f"cache missing: {p}")
    meta = json.loads(meta_p.read_text(encoding="utf-8"))
    expected_contract = cache_contract(task, split, source_sha256, rows)
    if meta["contract"] != expected_contract:
        diff = sorted(k for k in expected_contract
                      if meta["contract"].get(k) != expected_contract[k])
        raise InterfaceError(f"stale/corrupt cache contract for {task}/{split}: {diff}")
    if meta["files"]["arr"] != sha256_file(arr_p) or meta["files"]["mask"] != sha256_file(mask_p):
        raise InterfaceError(f"cache file digest mismatch for {task}/{split}")
    X = np.load(arr_p, allow_pickle=False)
    ok = np.load(mask_p, allow_pickle=False)
    if X.shape != (len(rows), FEATURE_DIM) or str(X.dtype) != "float32":
        raise InterfaceError(f"cache array shape/dtype invalid: {X.shape} {X.dtype}")
    if ok.shape != (len(rows),) or ok.dtype != np.bool_:
        raise InterfaceError(f"cache mask shape/dtype invalid: {ok.shape} {ok.dtype}")
    if array_digest(X)["sha256"] != meta["identity"]["features"]["sha256"]:
        raise InterfaceError(f"cache content digest mismatch (reordered/tampered?): {task}/{split}")
    if not np.isfinite(X).all():
        raise InterfaceError(f"cache contains non-finite values: {task}/{split}")
    if int(ok.sum()) != meta["identity"]["parsed_true_count"]:
        raise InterfaceError(f"parse mask population changed: {task}/{split}")
    if (array_digest(ok) != meta["identity"]["parse_mask"]
            or list(np.nonzero(~ok)[0]) != meta["identity"]["unparsed_row_indices"]
            or not (X[~ok] == GLOBAL_FILL_VALUE).all()):
        raise InterfaceError("parse mask/zero-fill identity mismatch")
    return X, ok


@dataclass
class FeatureScaler:
    """Fit-only feature standardization with explicit fit-partition identity."""

    mean: Any            # np.ndarray float32 [d]
    std: Any             # np.ndarray float32 [d]
    fit_partition: str   # always "official_train.fit_subset"
    fit_row_indices_sha256: str
    fit_n_rows: int
    epsilon: float = 1e-8

    def apply(self, X):
        import numpy as np
        A = np.asarray(X, dtype=np.float32)
        if A.ndim != 2 or A.shape[1] != self.mean.shape[0]:
            raise InterfaceError(f"scaler.apply shape invalid: {A.shape}")
        if not np.isfinite(A).all():
            raise InterfaceError("scaler.apply received non-finite raw features; "
                                 "fill unparseable rows first (fill_raw)")
        return ((A - self.mean) / self.std).astype(np.float32)

    def to_dict(self) -> dict[str, Any]:
        import numpy as np
        return {
            "kind": "feature_standardize_fit_only",
            "fit_partition": self.fit_partition,
            "fit_row_indices_sha256": self.fit_row_indices_sha256,
            "fit_n_rows": self.fit_n_rows,
            "epsilon": self.epsilon,
            "mean": np.asarray(self.mean).tolist(),
            "std": np.asarray(self.std).tolist(),
        }

    @staticmethod
    def from_dict(d: Mapping[str, Any]) -> "FeatureScaler":
        import numpy as np
        if d.get("kind") != "feature_standardize_fit_only":
            raise InterfaceError("unknown scaler kind")
        return FeatureScaler(
            mean=np.asarray(d["mean"], dtype=np.float32),
            std=np.asarray(d["std"], dtype=np.float32),
            fit_partition=d["fit_partition"],
            fit_row_indices_sha256=d["fit_row_indices_sha256"],
            fit_n_rows=int(d["fit_n_rows"]),
            epsilon=float(d["epsilon"]),
        )


def fill_raw(X):
    """Accept already filled, validated raw cache; never hide corrupt finite rows."""
    import numpy as np
    A = np.asarray(X, dtype=np.float32)
    if not np.isfinite(A).all():
        raise InterfaceError("raw cache must be finite; parse-mask fill occurs at encoding")
    return A


def fit_feature_scaler(X_filled_fit, fit_row_indices: Sequence[int]) -> FeatureScaler:
    """Standardize columns using ONLY the given fit-partition rows of official train."""
    import numpy as np
    A = np.asarray(X_filled_fit, dtype=np.float32)
    if A.ndim != 2 or A.shape[0] == 0:
        raise InterfaceError("fit_feature_scaler needs a non-empty 2-D fit matrix")
    if len(fit_row_indices) != len(A) or len(set(fit_row_indices)) != len(A):
        raise InterfaceError("fit matrix rows must match distinct fit row indices")
    if not np.isfinite(A).all():
        raise InterfaceError("fit matrix has non-finite values; fill before fitting")
    mu = A.mean(axis=0)
    sd = A.std(axis=0)
    eps = 1e-8
    sd = np.where(sd < eps, 1.0, sd)
    return FeatureScaler(
        mean=mu.astype(np.float32), std=sd.astype(np.float32),
        fit_partition="official_train.fit_subset",
        fit_row_indices_sha256=sha256_hex(canonical_json_bytes(sorted(fit_row_indices))),
        fit_n_rows=A.shape[0], epsilon=eps,
    )


@dataclass
class TargetScaler:
    """Regression-target standardization fitted on the fit partition only."""

    mean: float
    std: float

    def transform(self, y):
        import numpy as np
        return (np.asarray(y, dtype=np.float64) - self.mean) / self.std

    def transform_f32(self, y):
        """float32 view for feeding torch training space (loss/MSE in float32)."""
        import numpy as np
        return self.transform(y).astype(np.float32)

    def inverse(self, z):
        import numpy as np
        return np.asarray(z, dtype=np.float64) * self.std + self.mean

    def to_dict(self) -> dict[str, Any]:
        return {"kind": "target_standardize_fit_only", "mean": float(self.mean),
                "std": float(self.std)}

    @staticmethod
    def from_dict(d: Mapping[str, Any]) -> "TargetScaler":
        if d.get("kind") != "target_standardize_fit_only":
            raise InterfaceError("unknown target scaler kind")
        mean, std = float(d["mean"]), float(d["std"])
        import math
        if not math.isfinite(mean) or not math.isfinite(std) or std <= 0:
            raise InterfaceError("invalid target std")
        return TargetScaler(mean=mean, std=std)


def fit_target_scaler(y_fit) -> TargetScaler:
    import numpy as np
    y = np.asarray(y_fit, dtype=np.float64)
    if y.size == 0 or not np.isfinite(y).all():
        raise InterfaceError("fit targets must be non-empty and finite")
    std = float(y.std())
    return TargetScaler(mean=float(y.mean()), std=(std if std > 0 else 1.0))

"""Local early-stop metrics with explicit per-task definitions and directions.

Definitions follow input/context/task-metrics.json (local, official-equivalence
unconfirmed) and the approved baseline semantics:
  AUROC     Mann-Whitney U with average ranks (equals trapezoidal AUC under ties)
  AUPRC     Average Precision, sklearn-style tied-group weighting
  MAE       mean absolute error on the original Y scale
  Spearman  Pearson correlation of average ranks

Direction comes from task-metrics.json: MAE minimize; AUROC/AP/Spearman maximize.
Undefined values (one-class labels, constant vectors) are reported as None and the
training loop must reject that task's configuration rather than silently swapping
metric or seed. Comparison uses ``value < best - MIN_DELTA`` for minimize so ties
keep the earlier epoch (symmetrically ``value > best + MIN_DELTA`` for maximize).
"""

from __future__ import annotations

import math
from typing import Any, Mapping, Sequence

from .common import InterfaceError, read_json

MIN_DELTA = 1e-7


def _check_pairs(y_true: Sequence[float], y_score: Sequence[float]) -> None:
    if len(y_true) != len(y_score):
        raise InterfaceError(f"length mismatch: {len(y_true)} vs {len(y_score)}")
    if len(y_true) == 0:
        raise InterfaceError("empty metric input")
    for v in list(y_true) + list(y_score):
        if not math.isfinite(float(v)):
            raise InterfaceError(f"non-finite value: {v!r}")


def _average_ranks(values: Sequence[float]) -> list[float]:
    n = len(values)
    order = sorted(range(n), key=lambda i: values[i])
    ranks = [0.0] * n
    i = 0
    while i < n:
        j = i
        while j + 1 < n and values[order[j + 1]] == values[order[i]]:
            j += 1
        if j > i:
            avg = (i + 1 + j + 1) / 2.0
            for k in range(i, j + 1):
                ranks[order[k]] = avg
        else:
            ranks[order[i]] = float(i + 1)
        i = j + 1
    return ranks


def auroc(y_true: Sequence[float], y_score: Sequence[float]) -> float | None:
    _check_pairs(y_true, y_score)
    labels = [float(y) for y in y_true]
    for lab in labels:
        if lab not in (0, 1):
            raise InterfaceError(f"AUROC requires binary labels, got {lab}")
    n_pos = sum(labels)
    n_neg = len(labels) - n_pos
    if n_pos == 0 or n_neg == 0:
        return None  # undefined for one-class; caller must reject, not substitute
    ranks = _average_ranks([float(s) for s in y_score])
    s = sum(r for r, lab in zip(ranks, labels) if lab == 1)
    return (s - n_pos * (n_pos + 1) / 2.0) / (n_pos * n_neg)


def average_precision(y_true: Sequence[float], y_score: Sequence[float]) -> float | None:
    _check_pairs(y_true, y_score)
    labels = [float(y) for y in y_true]
    for lab in labels:
        if lab not in (0, 1):
            raise InterfaceError(f"AP requires binary labels, got {lab}")
    n = len(labels)
    n_pos = sum(labels)
    if n_pos == 0 or n_pos == n:
        return None
    order = sorted(range(n), key=lambda i: -float(y_score[i]))
    tp = fp = 0
    prev_recall = 0.0
    ap = 0.0
    i = 0
    while i < n:
        j = i
        score = float(y_score[order[i]])
        group_pos = group_neg = 0
        while j < n and float(y_score[order[j]]) == score:
            if labels[order[j]] == 1:
                group_pos += 1
            else:
                group_neg += 1
            j += 1
        tp += group_pos
        fp += group_neg
        recall = tp / n_pos
        precision = tp / (tp + fp)
        if group_pos:
            ap += precision * (recall - prev_recall)
        prev_recall = recall
        i = j
    return ap


def mae(y_true: Sequence[float], y_pred: Sequence[float]) -> float:
    _check_pairs(y_true, y_pred)
    return sum(abs(float(a) - float(b)) for a, b in zip(y_true, y_pred)) / len(y_true)


def spearman(y_true: Sequence[float], y_pred: Sequence[float]) -> float | None:
    _check_pairs(y_true, y_pred)
    n = len(y_true)
    if n < 2:
        return None
    rx = _average_ranks([float(v) for v in y_true])
    ry = _average_ranks([float(v) for v in y_pred])
    mx = sum(rx) / n
    my = sum(ry) / n
    cov = sum((a - mx) * (b - my) for a, b in zip(rx, ry))
    vx = sum((a - mx) ** 2 for a in rx)
    vy = sum((b - my) ** 2 for b in ry)
    if vx == 0.0 or vy == 0.0:
        return None
    return cov / math.sqrt(vx * vy)


METRIC_FUNCS = {
    "AUROC": auroc,
    "AUPRC": average_precision,
    "MAE": mae,
    "Spearman": spearman,
}


class EarlyStopMonitor:
    """Config-driven monitor bound to one task's local metric definition."""

    def __init__(self, metric: str, direction: str):
        if metric not in METRIC_FUNCS:
            raise InterfaceError(f"unsupported metric: {metric!r}")
        if direction not in ("minimize", "maximize"):
            raise InterfaceError(f"unknown direction: {direction!r}")
        if direction != ("minimize" if metric == "MAE" else "maximize"):
            raise InterfaceError("metric/direction contradiction")
        self.metric = metric
        self.direction = direction
        self.best_value: float | None = None
        self.best_epoch: int | None = None
        self.undefined_epochs: list[int] = []

    def observe(self, y_true: Sequence[float], y_pred: Sequence[float],
                epoch: int) -> dict[str, Any]:
        if self.undefined_epochs:
            raise InterfaceError("monitor previously invalid; this run remains rejected")
        try:
            value = METRIC_FUNCS[self.metric](y_true, y_pred)
        except (ValueError, OverflowError) as exc:
            self.undefined_epochs.append(epoch)
            raise InterfaceError(f"invalid monitor input at epoch {epoch}: {exc}") from exc
        record: dict[str, Any] = {"epoch": epoch, "metric": self.metric, "value": value}
        if value is None or not math.isfinite(value):
            self.undefined_epochs.append(epoch)
            raise InterfaceError(f"undefined/nonfinite {self.metric} at epoch {epoch}; reject task")
        if self.best_value is None:
            improved = True
        elif self.direction == "minimize":
            improved = value < self.best_value - MIN_DELTA
        else:
            improved = value > self.best_value + MIN_DELTA
        if improved:
            self.best_value = float(value)
            self.best_epoch = epoch
        record["improved"] = improved
        record["best_value"] = self.best_value
        record["best_epoch"] = self.best_epoch
        return record

    def should_stop(self, epoch: int, patience: int) -> bool:
        if self.best_epoch is None:
            return False
        return epoch - self.best_epoch >= patience


def load_task_metrics(path) -> dict[str, dict[str, str]]:
    """Read the registered task-metrics contract; validates shape of every entry."""
    data = read_json(path)
    out: dict[str, dict[str, str]] = {}
    for task, d in data.items():
        for key in ("metric", "direction", "definition"):
            if key not in d:
                raise InterfaceError(f"task-metrics[{task}] missing {key}")
        if d["metric"] not in METRIC_FUNCS:
            raise InterfaceError(f"task-metrics[{task}] unsupported metric {d['metric']}")
        EarlyStopMonitor(d["metric"], d["direction"])
        from .common import task_kind
        allowed = ("AUROC", "AUPRC") if task_kind(task) == "classification" else ("MAE", "Spearman")
        if d["metric"] not in allowed:
            raise InterfaceError(f"task-metrics[{task}] metric incompatible with task kind")
        out[task] = {"metric": d["metric"], "direction": d["direction"],
                     "definition": d["definition"]}
    return out

"""Per-row prediction records and official-template submission export.

Prediction record contract: (task, split, row_index, y_pred) with row_index the
0-based original data-row position within that task/split CSV. Every row of a
requested split receives a finite prediction (unparseable SMILES keep their
zero-filled embedding), so coverage is complete by construction and verifiable.

Template export guarantees (verified, not assumed):
  * output bytes preserve the template's UTF-8 BOM presence, CRLF endings, header,
    row order and every non-y_pred field exactly; only the y_pred cell changes;
  * refuses on missing/extra/duplicate (task, sample_idx) keys or wrong task set;
  * classification probabilities must lie in [0, 1]; all values must be finite.
"""

from __future__ import annotations

import csv
import io
import json
import math
from pathlib import Path
from typing import Any, Iterable, Mapping, Sequence

from .common import (InterfaceError, TASKS, TEMPLATE_ROWS, read_json)


def write_predictions_csv(path: Path, records: Sequence[Mapping[str, Any]]) -> dict[str, Any]:
    """Write task,split,row_index,y_pred rows (.10g format). Validates each record."""
    path = Path(path)
    path.parent.mkdir(parents=True, exist_ok=True)
    with open(path, "w", newline="", encoding="utf-8") as fh:
        w = csv.writer(fh)
        w.writerow(["task", "split", "row_index", "y_pred"])
        for r in records:
            v = float(r["y_pred"])
            if not math.isfinite(v):
                raise InterfaceError(f"non-finite y_pred: {r}")
            if r["split"] not in ("train", "valid", "test"):
                raise InterfaceError(f"bad split: {r}")
            if r["task"] not in TASKS:
                raise InterfaceError(f"bad task: {r}")
            w.writerow([r["task"], r["split"], int(r["row_index"]), f"{v:.10g}"])
    return {"path": str(path), "n_records": len(records)}


def load_predictions(path: Path | str) -> list[dict[str, Any]]:
    """Load prediction records from csv/json/jsonl; strict validation."""
    path = Path(path)
    if not path.is_file():
        raise InterfaceError(f"predictions file missing: {path}")
    text = path.read_bytes().decode("utf-8-sig")
    recs: list[dict[str, Any]] = []
    if path.suffix == ".json" or text.lstrip().startswith("["):
        data = json.loads(text)
        if not isinstance(data, list):
            raise InterfaceError("JSON predictions must be a top-level list")
        for i, r in enumerate(data):
            recs.append(_coerce(r, f"{path}:item{i}"))
    elif path.suffix == ".jsonl":
        for ln, line in enumerate(text.splitlines(), 1):
            if line.strip():
                recs.append(_coerce(json.loads(line), f"{path}:{ln}"))
    else:
        reader = csv.DictReader(io.StringIO(text, newline=""))
        if reader.fieldnames is None:
            raise InterfaceError(f"{path}: empty CSV")
        need = {"task", "split", "row_index", "y_pred"}
        if not need.issubset(set(reader.fieldnames)):
            raise InterfaceError(f"{path}: header missing {sorted(need - set(reader.fieldnames))}")
        for ln, row in enumerate(reader, 2):
            recs.append(_coerce(row, f"{path}:{ln}"))
    return recs


def _coerce(r: Mapping[str, Any], where: str) -> dict[str, Any]:
    try:
        task = str(r["task"])
        split = str(r["split"])
        ri = int(str(r["row_index"]).strip())
        yp = float(str(r["y_pred"]).strip())
    except KeyError as e:
        raise InterfaceError(f"{where}: missing key {e}") from None
    except (TypeError, ValueError) as e:
        raise InterfaceError(f"{where}: bad number ({e})") from None
    if task not in TASKS:
        raise InterfaceError(f"{where}: unknown task {task!r}")
    if split not in ("train", "valid", "test"):
        raise InterfaceError(f"{where}: split must be train/valid/test, got {split!r}")
    if not math.isfinite(yp):
        raise InterfaceError(f"{where}: non-finite y_pred {yp!r}")
    return {"task": task, "split": split, "row_index": ri, "y_pred": yp}


def check_coverage(records: Iterable[Mapping[str, Any]], expected_keys: set[tuple]) -> dict[str, Any]:
    seen: dict[tuple, int] = {}
    for rec in records:
        key = (rec["task"], rec["split"], rec["row_index"])
        seen[key] = seen.get(key, 0) + 1
    missing = sorted(k for k in expected_keys if k not in seen)
    extra = sorted(k for k in seen if k not in expected_keys)
    duplicates = {k: c for k, c in seen.items() if c > 1}
    return {
        "n_expected": len(expected_keys), "n_seen": len(seen),
        "missing_count": len(missing), "extra_count": len(extra),
        "duplicate_count": len(duplicates),
        "missing_head": missing[:10], "extra_head": extra[:10],
        "ok": not missing and not extra and not duplicates,
    }


def expected_test_keys(split_row_counts: Mapping[str, int]) -> set[tuple]:
    """Expected (task, 'test', row_index) keys from authoritative per-split counts."""
    return {(t, "test", i) for t, n in split_row_counts.items() for i in range(n)}


def _fmt(x: float) -> str:
    if x == int(x) and abs(x) < 1e16:
        return repr(float(x))
    return repr(x)


def export_submission(template_path: Path | str, predictions: Sequence[Mapping[str, Any]],
                      out_path: Path | str, *, probability_bounds: Mapping[str, bool] | None = None,
                      fixture: bool = False) -> dict[str, Any]:
    """Fill the official template's y_pred column ONLY.

    probability_bounds maps task -> True when its Y is a probability required to
    lie in [0,1] (classification tasks). fixture=True marks the run as a synthetic
    export check; it does not change byte semantics but is recorded in the summary.
    """
    from .common import CLASSIFICATION_TASKS

    template_path = Path(template_path)
    raw = template_path.read_bytes()
    has_bom = raw[:3] == b"\xef\xbb\xbf"
    text = raw.decode("utf-8-sig")
    crlf = "\r\n" in text
    lines = text.split("\r\n" if crlf else "\n")
    trailing_newline = False
    if lines and lines[-1] == "":
        lines = lines[:-1]
        trailing_newline = True
    header = lines[0]
    data_lines = lines[1:]
    if len(data_lines) != TEMPLATE_ROWS:
        raise InterfaceError(f"template data rows {len(data_lines)} != {TEMPLATE_ROWS}")
    hdr_cols = next(csv.reader([header]))
    if hdr_cols[:6] != ["task", "sample_idx", "drug_id", "smiles", "y_pred", "metric"]:
        raise InterfaceError(f"unexpected template header: {hdr_cols}")
    ypred_col = hdr_cols.index("y_pred")

    parsed = [next(csv.reader([ln])) for ln in data_lines]
    keys: dict[tuple, int] = {}
    for i, cols in enumerate(parsed):
        if len(cols) != len(hdr_cols):
            raise InterfaceError(f"template row {i} has {len(cols)} cols")
        key = (cols[0], cols[1])
        if key in keys:
            raise InterfaceError(f"duplicate template key {key}")
        keys[key] = i

    by_key: dict[tuple, float] = {}
    for rec in predictions:
        if rec["split"] != "test":
            raise InterfaceError(f"export requires split=='test', got {rec['split']!r}")
        key = (rec["task"], str(rec["row_index"]))
        if key in by_key:
            raise InterfaceError(f"duplicate prediction key {key}")
        if key not in keys:
            raise InterfaceError(f"prediction key not in template: {key}")
        yp = float(rec["y_pred"])
        if not math.isfinite(yp):
            raise InterfaceError(f"non-finite y_pred at {key}: {yp!r}")
        is_prob = (probability_bounds or {}).get(rec["task"], rec["task"] in CLASSIFICATION_TASKS)
        if is_prob and not (0.0 <= yp <= 1.0):
            raise InterfaceError(f"probability out of [0,1] at {key}: {yp!r}")
        by_key[key] = yp

    missing = [k for k in keys if k not in by_key]
    if missing:
        raise InterfaceError(f"{len(missing)} template keys lack predictions (first {missing[:5]})")

    out_lines = [header]
    for i, line in enumerate(data_lines):
        cols = parsed[i]
        cols[ypred_col] = _fmt(by_key[(cols[0], cols[1])])
        buf = io.StringIO()
        w = csv.writer(buf, lineterminator="")
        w.writerow(cols)
        out_lines.append(buf.getvalue())

    out_text = ("\r\n" if crlf else "\n").join(out_lines)
    if trailing_newline:
        out_text += "\r\n" if crlf else "\n"
    out_bytes = out_text.encode("utf-8")
    if has_bom:
        out_bytes = b"\xef\xbb\xbf" + out_bytes
    out_path = Path(out_path)
    out_path.parent.mkdir(parents=True, exist_ok=True)
    out_path.write_bytes(out_bytes)
    return {
        "out": str(out_path), "bytes": len(out_bytes), "rows": len(data_lines),
        "bom_preserved": has_bom, "crlf_preserved": crlf,
        "filled": len(by_key), "fixture": bool(fixture),
    }

